import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { map, catchError, tap } from 'rxjs/operators';
import { environment } from '../../environments/environment';

export interface ConciliacionDisponible {
  conciliacion_id: number;
  denuncia_id: number;
  numero_expediente: string;
  denunciante: string;
  fecha_audiencia: string;
  fecha_consolidacion: string;
  total_votos: number;
  votos_favor: number;
  votos_contra: number;
  resultado_final: string;
  tiene_medida_cautelar: boolean;
  medida_cautelar?: {
    medida_id: number;
    tipo_medida: string;
    fecha_inicio: string;
    estado: string;
    vigente: boolean;
  };
  estado: string;
  puede_seleccionarse: boolean;
  tipo_disponibilidad: string;
}

export interface VerificacionDisponibilidad {
  puede: boolean;
  motivos: string[];
  datos: {
    conciliacion_id: number;
    estado: string;
    total_votos: number;
    tiene_medida_cautelar: boolean;
    tiene_sentencia: boolean;
  };
}

@Injectable({
  providedIn: 'root'
})
export class ConciliacionDisponibleService {
  private apiUrl = `${environment.apiUrl}`;

  constructor(private http: HttpClient) {}

  /**
   * Obtener conciliaciones disponibles para sentencia
   */
  getParaSentencia(): Observable<ConciliacionDisponible[]> {
    return this.http.get<any>(`${this.apiUrl}/conciliaciones-disponibles/para-sentencia`).pipe(
      tap(response => console.log('📥 Conciliaciones para sentencia:', response)),
      map(response => response.success ? response.data : []),
      catchError(this.handleError)
    );
  }

  /**
   * Obtener conciliaciones disponibles para medida cautelar
   */
  getParaMedidaCautelar(): Observable<ConciliacionDisponible[]> {
    return this.http.get<any>(`${this.apiUrl}/conciliaciones-disponibles/para-medida-cautelar`).pipe(
      tap(response => console.log('📥 Conciliaciones para medida:', response)),
      map(response => response.success ? response.data : []),
      catchError(this.handleError)
    );
  }

  /**
   * Obtener todas las conciliaciones consolidadas
   */
  getConsolidadas(): Observable<ConciliacionDisponible[]> {
    return this.http.get<any>(`${this.apiUrl}/conciliaciones-disponibles/consolidadas`).pipe(
      map(response => response.success ? response.data : []),
      catchError(this.handleError)
    );
  }

  /**
   * Verificar disponibilidad de una conciliación específica
   */
  verificar(conciliacionId: number): Observable<{
    para_sentencia: VerificacionDisponibilidad;
    para_medida_cautelar: VerificacionDisponibilidad;
  }> {
    return this.http.get<any>(`${this.apiUrl}/conciliaciones-disponibles/${conciliacionId}/verificar`).pipe(
      map(response => response.success ? response.data : null),
      catchError(this.handleError)
    );
  }

  private handleError(error: any): Observable<never> {
    console.error('Error en ConciliacionDisponibleService:', error);
    return throwError(() => new Error('Error al obtener conciliaciones disponibles'));
  }
  /**
 * Obtener conciliaciones disponibles para NUEVA conciliación
 * (Excluye las que están COMPLETAS o tienen sentencia/medida)
 */
getParaNuevaConciliacion(): Observable<ConciliacionDisponible[]> {
  return this.http.get<any>(`${this.apiUrl}/conciliaciones-disponibles/nueva-conciliacion`).pipe(
    tap(response => console.log('📥 Conciliaciones para nueva conciliación:', response)),
    map(response => response.success ? response.data : []),
    catchError(this.handleError)
  );
}

/**
 * Obtener conciliaciones disponibles para REMISIÓN
 * (Con sentencia o medida cautelar fallida)
 */
getParaRemision(): Observable<any[]> {
  return this.http.get<any>(`${this.apiUrl}/conciliaciones-disponibles/remision`).pipe(
    tap(response => console.log('📥 Conciliaciones para remisión:', response)),
    map(response => response.success ? response.data : []),
    catchError(this.handleError)
  );
}
}
