import { Injectable } from '@angular/core';
import { HttpClient, HttpParams, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { environment } from '../../environments/environment';
import {
  Denuncia,
  ApiResponse,
  PaginatedResponse,
  DenunciaFilters,
  CrearDenunciaDTO,
  ActualizarDenunciaDTO,
  CambiarEstadoDTO,
  CrearInvolucradoDTO,
  Involucrado,
  HistorialItem
} from '../interfaces/denuncia.interface';
import { CatalogoService } from './catalogo.service';
import { PersonaService } from './persona.service';

@Injectable({
  providedIn: 'root'
})
export class DenunciaService {
  private baseUrl = `${environment.apiUrl}`;

  constructor(
    private http: HttpClient,
    public catalogoService: CatalogoService,
    public personaService: PersonaService
  ) {}

  // ========== MÉTODOS DE CATÁLOGOS (ADAPTADOS) ==========
  getTiposConflicto() {
    return this.catalogoService.getTiposConflicto();
  }

  getEstadosDenuncia() {
    return this.catalogoService.getEstadosDenuncia();
  }


  // ========== MÉTODOS DE PERSONAS ==========
  getUsuarioActual(): Observable<any> {
    return this.http.get(`${this.baseUrl}/auth/me`);
  }

  // ========== MÉTODOS PRINCIPALES DE DENUNCIAS ==========
  getDenuncias(filters: DenunciaFilters = {}): Observable<PaginatedResponse<Denuncia>> {
    let params = new HttpParams();

    Object.entries(filters).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '') {
        params = params.set(key, value.toString());
      }
    });

    return this.http.get<PaginatedResponse<Denuncia>>(`${this.baseUrl}/denuncias`, { params });
  }

  getDenuncia(id: number): Observable<ApiResponse<Denuncia>> {
    return this.http.get<ApiResponse<Denuncia>>(`${this.baseUrl}/denuncias/${id}`);
  }

  crearDenuncia(dto: CrearDenunciaDTO): Observable<ApiResponse<Denuncia>> {
    return this.http.post<ApiResponse<Denuncia>>(`${this.baseUrl}/denuncias`, dto);
  }

  crearDenunciaConArchivos(formData: FormData): Observable<ApiResponse<Denuncia>> {
    return this.http.post<ApiResponse<Denuncia>>(`${this.baseUrl}/denuncias`, formData);
  }

  actualizarDenuncia(id: number, dto: ActualizarDenunciaDTO): Observable<ApiResponse<Denuncia>> {
    return this.http.put<ApiResponse<Denuncia>>(`${this.baseUrl}/denuncias/${id}`, dto);
  }

  eliminarDenuncia(id: number): Observable<ApiResponse<null>> {
    return this.http.delete<ApiResponse<null>>(`${this.baseUrl}/denuncias/${id}`);
  }

  generarCodigoUnico(): Observable<ApiResponse<{ codigo: string }>> {
    return this.http.get<ApiResponse<{ codigo: string }>>(`${this.baseUrl}/denuncias/generar-codigo`);
  }

  buscarDenuncias(searchTerm: string): Observable<PaginatedResponse<Denuncia>> {
    return this.getDenuncias({ search: searchTerm, per_page: 20 });
  }

  // ========== MÉTODOS DE ACCIONES ==========
  cambiarEstado(id: number, dto: CambiarEstadoDTO): Observable<ApiResponse<Denuncia>> {
    return this.http.post<ApiResponse<Denuncia>>(`${this.baseUrl}/denuncias/${id}/cambiar-estado`, dto);
  }

  getResumenDenuncia(id: number): Observable<ApiResponse<any>> {
    return this.http.get<ApiResponse<any>>(`${this.baseUrl}/denuncias/${id}/resumen`);
  }

  generarReporteCompleto(id: number): Observable<ApiResponse<any>> {
    return this.http.get<ApiResponse<any>>(`${this.baseUrl}/denuncias/${id}/reporte-completo`);
  }

  validarEvidencia(id: number): Observable<ApiResponse<any>> {
    return this.http.post<ApiResponse<any>>(`${this.baseUrl}/denuncias/${id}/validar-evidencia`, {});
  }

  // ========== MÉTODOS DE HISTORIAL ==========
  getHistorial(id: number): Observable<ApiResponse<HistorialItem[]>> {
    return this.http.get<ApiResponse<HistorialItem[]>>(`${this.baseUrl}/denuncias/${id}/historial`);
  }

  // ========== MÉTODOS DE INVOLUCRADOS ==========
  getInvolucradosPorDenuncia(denunciaId: number): Observable<ApiResponse<Involucrado[]>> {
    return this.http.get<ApiResponse<Involucrado[]>>(`${this.baseUrl}/denuncias/${denunciaId}/involucrados`);
  }

  agregarInvolucrado(dto: CrearInvolucradoDTO): Observable<ApiResponse<Denuncia>> {
    return this.http.post<ApiResponse<Denuncia>>(
      `${this.baseUrl}/denuncias/${dto.denuncia_id}/involucrados`,
      dto
    );
  }

  eliminarInvolucrado(id: number): Observable<ApiResponse<null>> {
    return this.http.delete<ApiResponse<null>>(`${this.baseUrl}/involucrados/${id}`);
  }

  // ========== MÉTODOS DE REPORTES ==========
  reportePorEstado(): Observable<ApiResponse<any[]>> {
    return this.http.get<ApiResponse<any[]>>(`${this.baseUrl}/reportes/denuncias/por-estado`);
  }

  reportePorConflicto(): Observable<ApiResponse<any[]>> {
    return this.http.get<ApiResponse<any[]>>(`${this.baseUrl}/reportes/denuncias/por-conflicto`);
  }

  reportePorFechas(fechaInicio: string, fechaFin: string): Observable<ApiResponse<any[]>> {
    const params = new HttpParams()
      .set('fecha_inicio', fechaInicio)
      .set('fecha_fin', fechaFin);
    return this.http.get<ApiResponse<any[]>>(`${this.baseUrl}/reportes/denuncias/por-fechas`, { params });
  }

  reporteTiemposResolucion(): Observable<ApiResponse<any[]>> {
    return this.http.get<ApiResponse<any[]>>(`${this.baseUrl}/reportes/denuncias/tiempos-resolucion`);
  }

  getEstadisticas(): Observable<ApiResponse<any>> {
    return this.http.get<ApiResponse<any>>(`${this.baseUrl}/denuncias/estadisticas`);
  }

exportarEstadisticasExcel(): Observable<Blob> {
    return this.http.get(`${this.baseUrl}/denuncias/exportar-estadisticas-excel`, {
        responseType: 'blob',
        headers: new HttpHeaders().set('Accept', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    });
}

exportarEstadisticasPDF(): Observable<Blob> {
    return this.http.get(`${this.baseUrl}/denuncias/exportar-estadisticas-pdf`, {
        responseType: 'blob',
        headers: new HttpHeaders().set('Accept', 'application/pdf')
    });
}
}
