import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';

export interface UsuarioListResponse {
  data: any[];
  meta: {
    total: number;
    per_page: number;
    current_page: number;
    last_page: number;
  };
}

@Injectable({ providedIn: 'root' })
export class UsuarioService {
  private readonly baseUrl = `${environment.apiUrl}`;

  constructor(private http: HttpClient) {}

  listar(filters: any = {}): Observable<UsuarioListResponse> {
    const params = this.buildParams(filters);
    return this.http.get<UsuarioListResponse>(`${this.baseUrl}/usuarios`, { params });
  }

  obtener(id: number): Observable<any> {
    return this.http.get(`${this.baseUrl}/usuarios/${id}`);
  }

  crear(usuario: any): Observable<any> {
    return this.http.post(`${this.baseUrl}/usuarios`, usuario);
  }

  actualizar(id: number, usuario: any): Observable<any> {
    return this.http.put(`${this.baseUrl}/usuarios/${id}`, usuario);
  }

  eliminar(id: number): Observable<any> {
    return this.http.delete(`${this.baseUrl}/usuarios/${id}`);
  }

  cambiarPassword(id: number, data: any): Observable<any> {
    return this.http.post(`${this.baseUrl}/usuarios/${id}/cambiar-password`, data);
  }

  desbloquear(id: number): Observable<any> {
    return this.http.post(`${this.baseUrl}/usuarios/${id}/desbloquear`, {});
  }

  private buildParams(filters: any): { [param: string]: string | number | boolean } {
    const params: { [param: string]: string | number | boolean } = {};
    if (filters.search) params['search'] = filters.search;
    if (filters.rol_id) params['rol_id'] = filters.rol_id;
    if (filters.activo !== null && filters.activo !== undefined) params['activo'] = filters.activo;
    if (filters.page) params['page'] = filters.page;
    if (filters.per_page) params['per_page'] = filters.per_page;
    return params;
  }
}
