import { Injectable, Inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

@Injectable({
  providedIn: 'root'
})
export class PdfViewerService {
  private pdfjsLib: any = null;
  private isBrowser: boolean;

  constructor(@Inject(PLATFORM_ID) private platformId: any) {
    this.isBrowser = isPlatformBrowser(this.platformId);
  }

  async loadPdfLibrary(): Promise<any> {
    if (!this.isBrowser) {
      return null;
    }

    if (this.pdfjsLib) {
      return this.pdfjsLib;
    }

    // Lazy load PDF.js solo en el navegador
const pdfModule = await import('pdfjs-dist');
    this.pdfjsLib = pdfModule;

    // Configurar worker
    this.pdfjsLib.GlobalWorkerOptions.workerSrc =
      'https://cdn.jsdelivr.net/npm/pdfjs-dist@4.6.102/legacy/build/pdf.worker.min.js';

    return this.pdfjsLib;
  }

  async getDocument(src: string | Uint8Array | ArrayBuffer): Promise<any> {
    if (!this.isBrowser) {
      return null;
    }

    const pdf = await this.loadPdfLibrary();
    if (!pdf) return null;

    return pdf.getDocument(src).promise;
  }
}
