import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { map, catchError, tap } from 'rxjs/operators';
import { environment } from '../../environments/environment';

export interface MedidaCautelar {
  medida_id: number;
  conciliacion_id: number;
  tipo_medida_id: number;
  fecha_inicio: string;
  duracion_dias?: number;
  descripcion: string;
  estado: string;
  observaciones?: string;
  fecha_creacion: string;

  // Relaciones
  conciliacion?: {
    conciliacion_id: number;
    denuncia_id: number;
    fecha_audiencia: string;
    resultado_final: string;
    denuncia?: {
      denuncia_id: number;
      numero_expediente: string;
      codigo_externo: string;
      descripcion: string;
      persona?: {
        nombres: string;
        apellidos: string;
      }
    }
  };
  tipo_medida?: {
    tipo_medida_id: number;
    nombre: string;
    descripcion: string;
  };

  // Para UI (calculados)
  estado_texto?: string;
  fecha_vencimiento?: string;
  dias_restantes?: number | null;
  esta_vigente?: boolean;
  denuncia_codigo?: string;
  denuncia_descripcion?: string;
  tipo_medida_nombre?: string;
}

export interface CreateMedidaCautelarDTO {
  conciliacion_id: number;
  tipo_medida_id: number;
  fecha_inicio: string;
  duracion_dias?: number;
  descripcion: string;
  estado: string;
  observaciones?: string;
}

export interface UpdateMedidaCautelarDTO {
  tipo_medida_id?: number;
  fecha_inicio?: string;
  duracion_dias?: number;
  descripcion?: string;
  estado?: string;
  observaciones?: string;
}

export interface ProrrogaDTO {
  dias_prorroga: number;
  motivo: string;
}

export interface MedidaCautelarStats {
  por_estado: Record<string, number>;
  por_tipo: Record<string, number>;
  vigentes: number;
  total: number;
  proximas_a_vencer: number;
}

@Injectable({
  providedIn: 'root'
})
export class MedidaCautelarService {
  private apiUrl = `${environment.apiUrl}`;

  constructor(private http: HttpClient) {}

  /**
   * Listar medidas cautelares con filtros
   */
  listarMedidas(filtros?: {
    conciliacion_id?: number;
    tipo_medida_id?: number;
    estado?: string;
    vigentes?: boolean;
    fecha_desde?: string;
    fecha_hasta?: string;
    page?: number;
    per_page?: number;
  }): Observable<{ data: MedidaCautelar[]; meta: any }> {
    let params = new HttpParams();

    if (filtros) {
      Object.entries(filtros).forEach(([key, value]) => {
        if (value !== undefined && value !== null && value !== '') {
          params = params.set(key, value.toString());
        }
      });
    }

    return this.http.get<any>(`${this.apiUrl}/medidas-cautelares`, { params }).pipe(
      tap(response => console.log('📥 Medidas cautelares recibidas:', response)),
      map(response => {
        if (response.success && response.data) {
          // Procesar cada medida para agregar datos de UI
          const data = response.data.map((medida: any) => this.procesarMedida(medida));
          return {
            data,
            meta: response.meta || {
              current_page: 1,
              last_page: 1,
              per_page: filtros?.per_page || 15,
              total: data.length
            }
          };
        }
        return { data: [], meta: { total: 0 } };
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Obtener una medida cautelar por ID
   */
  obtenerMedida(id: number): Observable<MedidaCautelar> {
    return this.http.get<any>(`${this.apiUrl}/medidas-cautelares/${id}`).pipe(
      tap(response => console.log(`📥 Medida ${id} recibida:`, response)),
      map(response => {
        if (response.success && response.data) {
          return this.procesarMedida(response.data);
        }
        throw new Error('Medida cautelar no encontrada');
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Crear nueva medida cautelar
   */
  crearMedida(dto: CreateMedidaCautelarDTO): Observable<MedidaCautelar> {
    console.log('📤 Creando medida cautelar:', dto);

    return this.http.post<any>(`${this.apiUrl}/medidas-cautelares`, dto).pipe(
      tap(response => console.log('📥 Respuesta creación medida:', response)),
      map(response => {
        if (response.success && response.data) {
          return this.procesarMedida(response.data);
        }
        throw new Error(response.message || 'Error al crear medida cautelar');
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Actualizar medida cautelar
   */
  actualizarMedida(id: number, dto: UpdateMedidaCautelarDTO): Observable<MedidaCautelar> {
    console.log('📤 Actualizando medida cautelar:', { id, dto });

    return this.http.put<any>(`${this.apiUrl}/medidas-cautelares/${id}`, dto).pipe(
      tap(response => console.log('📥 Respuesta actualización medida:', response)),
      map(response => {
        if (response.success && response.data) {
          return this.procesarMedida(response.data);
        }
        throw new Error(response.message || 'Error al actualizar medida cautelar');
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Eliminar medida cautelar
   */
  eliminarMedida(id: number): Observable<boolean> {
    return this.http.delete<any>(`${this.apiUrl}/medidas-cautelares/${id}`).pipe(
      map(response => response.success),
      catchError(this.handleError)
    );
  }

  /**
   * Cambiar estado de medida cautelar
   */
  cambiarEstado(id: number, estado: string, observaciones?: string): Observable<MedidaCautelar> {
    return this.http.patch<any>(`${this.apiUrl}/medidas-cautelares/${id}/cambiar-estado`, {
      estado,
      observaciones
    }).pipe(
      map(response => {
        if (response.success && response.data) {
          return this.procesarMedida(response.data);
        }
        throw new Error(response.message || 'Error al cambiar estado');
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Prorrogar medida cautelar
   */
  prorrogarMedida(id: number, dto: ProrrogaDTO): Observable<MedidaCautelar> {
    return this.http.post<any>(`${this.apiUrl}/medidas-cautelares/${id}/prorrogar`, dto).pipe(
      map(response => {
        if (response.success && response.data) {
          return this.procesarMedida(response.data);
        }
        throw new Error(response.message || 'Error al prorrogar medida');
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Obtener estadísticas
   */
  obtenerEstadisticas(): Observable<MedidaCautelarStats> {
    return this.http.get<any>(`${this.apiUrl}/medidas-cautelares/estadisticas`).pipe(
      map(response => {
        if (response.success && response.data) {
          return response.data;
        }
        return {
          por_estado: {},
          por_tipo: {},
          vigentes: 0,
          total: 0,
          proximas_a_vencer: 0
        };
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Procesar medida para UI
   */
  private procesarMedida(medida: any): MedidaCautelar {
    // Extraer información de denuncia
    let denunciaCodigo = '';
    let denunciaDescripcion = '';

    if (medida.conciliacion) {
      if (medida.conciliacion.denuncia) {
        denunciaCodigo = medida.conciliacion.denuncia.numero_expediente ||
                        medida.conciliacion.denuncia.codigo_externo ||
                        `DEN-${medida.conciliacion.denuncia.denuncia_id}`;
        denunciaDescripcion = medida.conciliacion.denuncia.descripcion || '';
      }
    }

    // Calcular fecha de vencimiento y días restantes
    let fechaVencimiento = null;
    let diasRestantes = null;
    let estaVigente = false;

    if (medida.fecha_inicio && medida.duracion_dias && medida.estado === 'ACTIVA') {
      const fechaInicio = new Date(medida.fecha_inicio);
      fechaVencimiento = new Date(fechaInicio);
      fechaVencimiento.setDate(fechaVencimiento.getDate() + medida.duracion_dias);

      const hoy = new Date();
      const diffTime = fechaVencimiento.getTime() - hoy.getTime();
      diasRestantes = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      estaVigente = diasRestantes > 0;
    }

    return {
      ...medida,
      estado_texto: this.getEstadoTexto(medida.estado),
      fecha_vencimiento: fechaVencimiento?.toISOString().split('T')[0],
      dias_restantes: diasRestantes,
      esta_vigente: estaVigente,
      denuncia_codigo: denunciaCodigo,
      denuncia_descripcion: denunciaDescripcion,
      tipo_medida_nombre: medida.tipo_medida?.nombre || 'Desconocido'
    };
  }

  /**
   * Obtener texto legible para estado
   */
  private getEstadoTexto(estado: string): string {
    const estados: Record<string, string> = {
      'ACTIVA': 'Activa',
      'CUMPLIDA': 'Cumplida',
      'VENCIDA': 'Vencida',
      'REVOCADA': 'Revocada',
      'SUSPENDIDA': 'Suspendida',
      'PRORROGADA': 'Prorrogada'
    };
    return estados[estado] || estado;
  }

  private handleError(error: any): Observable<never> {
    console.error('Error en MedidaCautelarService:', error);
    let errorMessage = 'Error en la operación';

    if (error.error instanceof ErrorEvent) {
      errorMessage = `Error: ${error.error.message}`;
    } else if (error.error?.message) {
      errorMessage = error.error.message;
    } else if (error.status === 404) {
      errorMessage = 'Recurso no encontrado';
    } else if (error.status === 422) {
      errorMessage = error.error?.message || 'Error de validación';
    }

    return throwError(() => new Error(errorMessage));
  }
}
